const STORAGE_KEY = 'badaHansang.sharedData.v1';
const seedBoats = [
  {id:'blue-sea',name:'푸른바다호',fisher:'김선장',port:'통영 · 욕지도',catch:'참돔 · 전갱이',icon:'⛵',logs:[{date:'2026. 07. 28.',title:'참돔 42kg · 전갱이 31kg',text:'동풍이 약해 욕지도 인근에서 안정적으로 조업 중입니다.',photos:[]}],products:[{id:'p1',name:'활참돔 1kg',price:28000,quantity:14,description:'오늘 선별한 활참돔입니다.',photo:''},{id:'p2',name:'전갱이 1kg',price:12000,quantity:20,description:'통영 연안에서 잡은 전갱이입니다.',photo:''}]},
  {id:'sunrise',name:'해맞이호',fisher:'박선장',port:'제주 · 성산',catch:'갈치 · 고등어',icon:'🛥️',logs:[{date:'2026. 07. 28.',title:'갈치 35kg · 고등어 60kg',text:'성산 앞바다에서 조업을 시작했습니다.',photos:[]}],products:[{id:'p3',name:'제주 은갈치 500g',price:24000,quantity:12,description:'제주 성산 앞바다 은갈치입니다.',photo:''}]},
  {id:'sea-star',name:'바다별호',fisher:'이선장',port:'여수 · 돌산',catch:'문어 · 갑오징어',icon:'🚤',logs:[{date:'2026. 07. 28.',title:'문어 18kg · 갑오징어 29kg',text:'돌산 연안 수온이 좋아 조업을 이어갑니다.',photos:[]}],products:[{id:'p4',name:'돌문어 500g',price:31000,quantity:8,description:'여수 돌산에서 잡은 문어입니다.',photo:''}]},
  {id:'safe-harbor',name:'든든한항구호',fisher:'최선장',port:'부산 · 영도',catch:'고등어 · 전갱이',icon:'🛟',logs:[{date:'2026. 07. 29.',title:'응원금으로 안전한 선박 수리를 진행합니다',text:'응원자분들이 보내주신 마음 덕분에 갑판과 장비를 정비하고 있습니다. 더 안전한 조업과 신선한 수산물로 보답하겠습니다.',photos:['assets/feed-repair-boat.png']}],products:[]}
];
const screen = document.querySelector('#screen');
const modalLayer = document.querySelector('#modal-layer');
let investmentCarouselTimer = null;
const today = () => new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit'}).replace(/\. /g,'. ').replace(/\.$/,'')+'.';
function db(){let raw=localStorage.getItem(STORAGE_KEY),data=raw?JSON.parse(raw):{};if((data.schemaVersion||0)<10){data={schemaVersion:10,boats:[],supports:{},supporterSupports:{},supporterAccounts:[],fisherAccounts:[],session:null,posts:[]}}data.boats??=[];data.supports??={};data.supporterSupports??={};data.supporterAccounts??=[];data.fisherAccounts??=[];data.posts??=[];data.orders??=[];if((data.schemaVersion||0)<11){data.supports={};data.supporterSupports={};data.orders=[];data.posts=data.posts.filter(p=>String(p.id).startsWith('welcome-'));data.boats.filter(b=>b.ownerId).forEach(b=>{b.logs=[];b.products=[]});data.schemaVersion=11}if(!data.session){try{const saved=JSON.parse(sessionStorage.getItem('fishFunding.activeSession'));if(saved)data.session=saved}catch{}}data.supporterAccounts.forEach(a=>{if(a.wallet==null)a.wallet=50000});seedBoats.forEach(b=>{if(!data.boats.some(x=>x.id===b.id))data.boats.push(structuredClone(b))});const seedFeed={"blue-sea":{title:'참돔 선별을 마치고 입항합니다',text:'오늘 새벽 조업을 마치고 참돔과 전갱이를 신선하게 선별 중입니다.',photo:'assets/feed-blue-sea.png'},sunrise:{title:'성산항 수산시장으로 향하는 고등어',text:'입항한 고등어를 꼼꼼히 선별해 오늘의 직송 준비를 마쳤습니다.',photo:'assets/feed-sunrise.png'},"sea-star":{title:'돌산 연안, 오징어 떼를 만났습니다',text:'맑은 바다 아래 오징어 떼가 보여 조업을 이어가고 있습니다.',photo:'assets/feed-sea-star.png'}};Object.entries(seedFeed).forEach(([id,entry])=>{const b=data.boats.find(x=>x.id===id);if(b?.logs?.[0]){b.logs[0].title=entry.title;b.logs[0].text=entry.text;b.logs[0].photos=[entry.photo]}});const seedPosts=[{id:'welcome-talk',category:'talk',author:'피시 펀딩 운영팀',title:'피시 펀딩 커뮤니티에 오신 것을 환영합니다',content:'조업 이야기, 바다에 대한 질문, 응원 메시지를 자유롭게 나눠 주세요. 서로의 오늘을 응원하는 따뜻한 공간입니다.',rating:0,photo:'',likes:12,comments:[{author:'바다지킴이',text:'어민분들의 안전한 조업을 응원합니다!',date:'2026. 07. 28.'}],date:'2026. 07. 28.'},{id:'welcome-recipe',category:'recipe',author:'통영 바다식탁',title:'통영 생굴 한입 오일파스타',content:'싱싱한 생굴은 마지막 1분에 넣어 살짝만 익혀 주세요. 마늘과 올리브유, 레몬즙만으로도 바다 향이 살아납니다.',rating:0,photo:'',likes:28,comments:[{author:'굴러버',text:'이번 주말에 꼭 만들어 볼게요.',date:'2026. 07. 28.'}],date:'2026. 07. 28.'},{id:'welcome-review',category:'review',author:'신선한식탁',title:'산지 직송 참돔 후기',content:'포장을 열자마자 신선함이 느껴졌어요. 가족들과 맑은탕으로 맛있게 먹었습니다.',rating:5,photo:'',likes:19,comments:[],date:'2026. 07. 28.'}];seedPosts.forEach(p=>{if(!data.posts.some(x=>x.id===p.id))data.posts.push(p)});save(data);return data}
function save(data){localStorage.setItem(STORAGE_KEY,JSON.stringify(data));if(data.session)sessionStorage.setItem('fishFunding.activeSession',JSON.stringify(data.session));else sessionStorage.removeItem('fishFunding.activeSession')}
function boat(id){return db().boats.find(x=>x.id===id)}
function money(n){return `${Number(n).toLocaleString('ko-KR')}원`}
function back(title,target='start'){return `<div class="title-row"><button class="back" data-go="${target}">‹</button><h1>${title}</h1></div>`}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}

function startInvestmentCarousel(){clearInterval(investmentCarouselTimer);const carousel=document.querySelector('.investment-carousel');if(!carousel)return;const originals=[...carousel.querySelectorAll('.investment-card')];let index=0;investmentCarouselTimer=setInterval(()=>{const el=document.querySelector('.investment-carousel');if(!el){clearInterval(investmentCarouselTimer);return}if(index>=el.children.length-2)el.appendChild(originals[index%originals.length].cloneNode(true));const card=el.querySelector('.investment-card'),step=card.offsetWidth+12;index++;el.scrollTo({left:index*step,behavior:'smooth'})},1500)}
function viewHome(){const data=db(),ranked=data.boats.slice().sort((a,b)=>(data.supports[b.id]||0)-(data.supports[a.id]||0)).slice(0,3),feed=data.boats.flatMap(b=>b.logs.map(l=>({boat:b,log:l}))).slice().reverse().slice(0,5);screen.innerHTML=`<section class="ocean-home"><div class="ocean-home-copy"><small>피시 펀딩 · 오늘의 바다</small><h1>오늘의 바다<br><em>한 스푼</em></h1><p>바다의 온도를 느끼고, 신선함에 투자하세요.</p></div><span class="home-boat">⛵</span></section><section class="sea-report"><div class="report-title"><span>🌤️</span><div><small>오늘의 바다 한 스푼</small><strong>맑음 · 잔잔한 파도</strong></div><b>통영</b></div><div class="report-stats"><div><span>파도 높이</span><strong>0.4m</strong></div><div><span>바다 상태</span><strong>매우 좋음</strong></div><div><span>수온</span><strong>23°C</strong></div></div><p>부드러운 바람과 잔잔한 물결, 오늘은 조업하기 좋은 날이에요.</p><article class="season-card"><span>🦪</span><div><small>오늘의 제철 해산물</small><strong>통영 생굴</strong><p>바다 향이 가득한, 지금 가장 맛있는 제철 한입</p></div></article></section><section class="home-section"><div class="home-section-title"><h2>인기 투자</h2><span>1초마다 자동으로 바뀌어요</span></div><div class="investment-carousel">${ranked.map((b,i)=>`<article class="investment-card"><div class="investment-picture">${b.icon||'⚓'}</div><small>${i===0?'이번 주 1위':'인기 어선'}</small><h3>${b.name}</h3><p>${b.fisher} 선장 · ${b.catch}</p><strong>💙 ${money(data.supports[b.id]||0)}</strong></article>`).join('')}<article class="investment-card farm-card"><div class="investment-picture">🦪</div><small>인기 양식장</small><h3>청정바다 굴 양식장</h3><p>통영 연안 · 제철 생굴</p><strong>💙 1,240,000원</strong></article></div></section><section class="home-section feed-section"><div class="home-section-title"><h2>어민 현장 피드</h2><span>오늘의 바다 이야기</span></div><div class="field-feed">${feed.length?feed.map(({boat:b,log:l})=>`<article class="feed-card"><div class="feed-head"><span>${b.icon||'⚓'}</span><div><strong>${b.name}</strong><small>${l.date} · ${b.fisher} 선장</small></div></div>${l.photos?.length?`<img src="${l.photos[0]}" alt="${b.name} 조업 현장">`:`<div class="feed-fallback">${b.icon||'⚓'}<span>오늘의 조업 현장</span></div>`}<h3>${l.title}</h3><p>${l.text}</p></article>`).join(''):`<article class="feed-card"><div class="feed-fallback">🌊<span>어민의 첫 현장 기록을 기다리고 있어요</span></div></article>`}</div></section><button class="community-entry" data-go="community"><span>💬</span><div><strong>커뮤니티</strong><small>어민과 소비자가 나누는 바다 이야기</small></div><i>›</i></button><button class="invest-fab" data-go="role-select">＋ <span>로그인하기</span></button>`;startInvestmentCarousel()}
function viewRoleSelect(){screen.innerHTML=back('피시 펀딩 시작')+`<section class="home-hero role-hero"><small>바다를 함께 키우는 방법</small><h1>어떤 방식으로<br>바다와 함께할까요?</h1><p>응원자는 신선한 수산물을 받고, 어부는 오늘의 바다를 기록합니다.</p></section><section class="home-actions"><button class="action-card" data-go="support-entry"><b>💙</b><span><strong>응원자</strong>어선을 응원하고 산지 직송 수산물을 만나보세요.</span><i>›</i></button><button class="action-card my" data-go="fisher-entry"><b>⚓</b><span><strong>어부</strong>조업을 기록하고 수산물을 판매해 보세요.</span><i>›</i></button></section>`}
function activeSupporter(data=db()){return data.session?.role==='supporter'&&data.supporterAccounts.find(a=>a.id===data.session.id)}
function viewSupportEntry(){const data=db();if(activeSupporter(data)){viewSupportHome();return}if(!data.supporterAccounts.length){viewSupportSignup();return}screen.innerHTML=back('응원자')+`<section class="empty"><b>💙</b><h2>응원자 계정</h2><p>기존 계정으로 로그인하거나 새 계정을 만드세요.</p><button class="primary-button full" data-go="support-login">기존 계정으로 로그인</button><button class="outline-button full" data-go="support-signup">새 계정 만들기</button></section>`}
function viewSupportSignup(){screen.innerHTML=back('응원자 회원가입','role-select')+`<form class="form-card" id="support-signup-form"><label>아이디<input name="username" required placeholder="아이디 입력"></label><label>비밀번호<input name="password" type="password" required placeholder="비밀번호 입력"></label><button class="primary-button full" type="submit">회원가입</button></form>`}
function viewSupportLogin(){const accounts=db().supporterAccounts;screen.innerHTML=back('응원자 로그인','role-select')+`<form class="form-card" id="support-login-form"><label>계정 선택<select name="accountId">${accounts.map(a=>`<option value="${a.id}">${a.username}</option>`).join('')}</select></label><label>비밀번호<input name="password" type="password" required placeholder="비밀번호 입력"></label><button class="primary-button full" type="submit">로그인</button></form>`}
function viewSupportHome(){const user=activeSupporter();screen.innerHTML=back('응원자')+`<section class="home-hero"><small>오늘의 바다를 함께 키워요</small><h1>바다의 하루가<br>당신의 식탁으로</h1><p>어선을 응원하고, 오늘 잡은 신선한 수산물을 직접 받아보세요.</p></section><section class="wallet-chip">👛 내 지갑 <strong>${(user.wallet||0).toLocaleString()}P</strong></section><section class="home-actions"><button class="action-card" data-go="boats"><b>⛵</b><span><strong>어선 목록 보기</strong>어선별 주요 어획물과 조업 일지를 살펴보세요.</span><i>›</i></button><button class="action-card my" data-go="my-boats"><b>🌊</b><span><strong>내 어선 현황 보기</strong>내가 응원한 어선과 받을 수산물을 확인하세요.</span><i>›</i></button><button class="action-card" data-go="my-orders"><b>📦</b><span><strong>구매 내역 보기</strong>주문·결제·배송 상태를 확인하세요.</span><i>›</i></button><button class="logout-button" data-logout>로그아웃</button></section>`}
function boatCard(b, mine=false){const data=db(),user=activeSupporter(data),support=mine?(user?data.supporterSupports[user.id]?.[b.id]||0:0):data.supports[b.id]||0,latest=b.logs.at(-1);return `<article class="boat-card"><div class="boat-icon">${b.icon||'⚓'}</div><div><div class="boat-top"><span>${b.port||'등록 어선'}</span><b class="status">${b.logs.length?'일지 업데이트':'조업 준비'}</b></div><h2>${b.name}</h2><p class="catch">${b.fisher} 선장 · ${b.catch||'어획물 정보 미등록'}</p>${mine&&latest?`<p class="latest-log">최신 조업 · ${latest.date} · ${latest.title}</p>`:''}<div class="boat-foot"><span>${mine?`내 응원금 ${money(support)} · 판매 ${b.products.length}종`:`판매 수산물 ${b.products.length}종`}</span><div class="card-buttons">${mine?`<button class="support-button" data-detail="${b.id}">내 어선 보기</button>`:`<button class="log-button" data-public-log="${b.id}">조업 일지</button><button class="log-button" data-public-products="${b.id}">수산물</button><button class="support-button" data-support="${b.id}">응원하기</button>`}</div></div></div></article>`}
function viewBoats(){const data=db();screen.innerHTML=back('어선 목록','support-home')+`<p class="subtitle">좌우로 밀어 여러 어선을 살펴보세요. 조업 일지와 판매 수산물도 바로 확인할 수 있어요.</p><section class="boat-list draggable-list">${data.boats.map(b=>boatCard(b)).join('')}</section>`}
function viewMyBoats(){const data=db(),user=activeSupporter(data),mine=data.boats.filter(b=>(data.supporterSupports[user.id]?.[b.id]||0)>0);screen.innerHTML=back('내 어선 현황','support-home')+(mine.length?`<p class="subtitle">응원한 어선을 선택해 조업 일지와 산지 직송 상품을 확인하세요.</p><section class="boat-list">${mine.map(b=>boatCard(b,true)).join('')}</section>`:`<section class="empty"><b>🌊</b><h2>아직 응원한 어선이 없어요</h2><p>마음에 드는 어선을 응원하면<br>이곳에서 조업 현황을 확인할 수 있어요.</p><button class="primary-button" data-go="boats">어선 목록 보기</button></section>`)}
function viewSupportDetail(id){const b=boat(id),data=db(),user=activeSupporter(data),amount=data.supporterSupports[user.id]?.[id]||0,latest=b.logs.at(-1);screen.innerHTML=back(b.name,'my-boats')+`<section class="detail-hero"><small>${b.port||'등록 어선'} · ${b.fisher} 선장</small><h2>${b.icon||'⚓'} ${b.name}</h2><p>주요 어획물 · ${b.catch||'정보 등록 전'}</p></section><section class="info-box"><span>내 누적 응원금</span><strong>${money(amount)}</strong></section><section class="tracking-card"><div class="tracking-head"><div><small>실시간 조업 타임라인</small><h3>📍 ${b.port||'연안'} 인근 조업 중</h3></div><b>LIVE</b></div><div class="timeline"><article class="done"><i>✓</i><div><small>05:30</small><strong>출항 완료</strong><p>항구를 출발해 조업 해역으로 이동했습니다.</p></div></article><article class="active"><i>●</i><div><small>현재</small><strong>${latest?.title||'오늘의 조업 진행 중'}</strong><p>${latest?.text||'선장이 오늘의 조업 상황을 기록하고 있습니다.'}</p></div></article><article><i>○</i><div><small>예정</small><strong>입항 · 선별 · 포장</strong><p>수산물 선별 후 주문 상품을 순차적으로 준비합니다.</p></div></article><article><i>○</i><div><small>다음</small><strong>산지 직송 배송</strong><p>배송 신청 상품은 출항·입항 상황에 맞춰 발송됩니다.</p></div></article></div></section><section class="detail-actions"><button class="outline-button" data-log="${id}" data-back="my-boats">조업 일지 보기</button><button class="primary-button" data-products="${id}">수산물 받기</button></section>`}
function viewLogs(id, backTo='support-detail'){const b=boat(id);screen.innerHTML=back(`${b.name} 조업 일지`,backTo)+`<p class="subtitle">${b.fisher} 선장이 직접 기록한 조업 상황입니다.</p><section class="log">${b.logs.length?b.logs.slice().reverse().map(l=>`<article class="log-item"><small>${l.date}</small><h3>${l.title||'오늘의 조업 기록'}</h3><p>${l.text}</p>${l.photos?.length?`<div class="photo-row">${l.photos.map(p=>`<img src="${p}" alt="조업 사진">`).join('')}</div>`:''}</article>`).join(''):`<section class="empty"><b>📝</b><h2>아직 작성된 조업 일지가 없어요</h2><p>선장이 첫 조업 기록을 남기면 이곳에 표시됩니다.</p></section>`}</section>`}
function viewProducts(id,backTo='my-boats'){const b=boat(id);screen.innerHTML=back('수산물 받기',backTo)+`<p class="subtitle">${b.name}에서 판매 중인 산지 직송 수산물입니다.</p>${b.products.length?`<section class="product-list">${b.products.map(p=>`<button class="product shop-product" data-product-detail="${b.id}|${p.id}"><span class="product-photo">${p.photo?`<img src="${p.photo}" alt="${p.name}">`:'🦪'}</span><span><strong>${p.name}</strong><span>${money(p.price)} · 재고 ${p.quantity}개</span></span><i>›</i></button>`).join('')}</section>`:`<section class="empty"><b>🧺</b><h2>판매 중인 수산물이 없어요</h2><p>선장이 상품을 등록하면 이곳에 표시됩니다.</p></section>`}`}
function viewProductDetail(boatId,productId){const b=boat(boatId),p=b.products.find(x=>x.id===productId);screen.innerHTML=back('상품 상세','boats')+`<section class="product-detail"><div class="detail-product-image">${p.photo?`<img src="${p.photo}" alt="${p.name}">`:'🦪'}</div><small>${b.name} · ${b.fisher} 선장</small><h2>${p.name}</h2><strong>${money(p.price)}</strong><p>${p.description||'신선한 산지 직송 수산물입니다.'}</p><div>재고 수량 <b>${p.quantity}개</b></div><button class="primary-button full" data-order-start="${boatId}|${productId}">구매하기</button></section>`}
function viewOrderForm(boatId,productId){const b=boat(boatId),p=b.products.find(x=>x.id===productId);screen.innerHTML=back('주문 정보 입력','boats')+`<form class="form-card" id="order-form"><input type="hidden" name="boatId" value="${boatId}"><input type="hidden" name="productId" value="${productId}"><section class="order-summary"><strong>${p.name}</strong><span>${money(p.price)} · 재고 ${p.quantity}개</span></section><label>구매 수량<input name="quantity" type="number" min="1" max="${p.quantity}" value="1" required></label><label>받는 사람 이름<input name="recipient" required></label><label>연락처<input name="phone" required placeholder="010-0000-0000"></label><label>배송 주소<input name="address" required placeholder="상세 주소까지 입력"></label><label>배송 요청사항<textarea name="request" placeholder="예: 부재 시 문 앞에 놓아 주세요."></textarea></label><button class="primary-button full" type="submit">결제 방식 선택</button></form>`}
function viewPayment(draft){const b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId),total=p.price*draft.quantity,user=activeSupporter();sessionStorage.setItem('fishFunding.orderDraft',JSON.stringify(draft));screen.innerHTML=back('결제 방식','support-home')+`<section class="order-summary"><strong>${p.name} × ${draft.quantity}</strong><span>결제 금액 <b>${money(total)}</b></span></section><form class="form-card" id="payment-form"><input type="hidden" name="total" value="${total}"><label><input type="radio" name="payment" value="reservation"> 예약 구매 <small>다음 조업 후 수산물을 확보해 순차 배송합니다.</small></label><label><input type="radio" name="payment" value="card" checked> 카드 결제 <select name="card"><option>테스트 신한카드</option><option>테스트 국민카드</option><option>테스트 현대카드</option></select></label><label><input type="radio" name="payment" value="transfer"> 계좌이체 <small>피시 펀딩 · 1002-000-123456 (테스트 계좌)</small></label><label><input type="radio" name="payment" value="wallet"> 포인트/지갑 <small>현재 잔액 ${user.wallet.toLocaleString()}P</small></label><button class="primary-button full" type="submit">테스트 결제 완료</button></form>`}
function viewMyOrders(){const data=db(),user=activeSupporter(data),orders=data.orders.filter(o=>o.supporterId===user.id).slice().reverse();screen.innerHTML=back('구매 내역','support-home')+(orders.length?`<section class="order-list">${orders.map(o=>`<article><strong>${o.productName}</strong><span>${o.status} · ${money(o.total)}</span><small>${o.date} · ${o.paymentLabel}</small></article>`).join('')}</section>`:`<section class="empty"><b>📦</b><h2>구매 내역이 없어요</h2><p>산지 직송 수산물을 주문해 보세요.</p></section>`)}
function openSupport(id){const b=boat(id),user=activeSupporter();screen.innerHTML=back(`${b.name} 응원하기`,'boats')+`<p class="subtitle">응원금은 유류비, 얼음, 어구 등 안전한 조업의 기본 비용으로 사용됩니다.</p><form class="form-card" id="support-order-form"><input type="hidden" name="boatId" value="${id}"><section class="order-summary"><strong>${b.icon||'⚓'} ${b.name}</strong><span>${b.fisher} 선장 · 조업 응원</span></section><label>응원자 아이디<input name="username" required value="${user?.username||''}" placeholder="응원자 아이디"></label><label>비밀번호<input name="password" type="password" required placeholder="비밀번호 입력"></label><label>응원 금액<input name="amount" type="number" inputmode="numeric" min="10000" step="1000" value="10000" required></label><p class="policy-note">응원금은 10,000원 이상부터 가능합니다.</p><button class="primary-button full" type="submit">결제 방식 선택</button></form>`}
function viewSupportPayment(draft){const b=boat(draft.boatId);sessionStorage.setItem('fishFunding.supportDraft',JSON.stringify(draft));screen.innerHTML=back('응원 결제','boats')+`<section class="order-summary"><strong>${b.name} 응원</strong><span>결제 금액 <b>${money(draft.amount)}</b></span></section><form class="form-card" id="support-payment-form"><label><input type="radio" name="payment" value="card" checked> 카드 결제 <select name="card"><option>테스트 신한카드</option><option>테스트 국민카드</option><option>테스트 현대카드</option></select></label><label>카드 번호<input name="cardNumber" inputmode="numeric" placeholder="0000-0000-0000-0000"></label><label>유효기간 / CVC<input name="cardInfo" placeholder="MM/YY · CVC"></label><label><input type="radio" name="payment" value="transfer"> 계좌이체 <small>피시 펀딩 · 1002-000-123456 (테스트 계좌)</small></label><p class="policy-note">계좌이체는 주문 후 ‘입금 확인 대기’ 상태로 저장됩니다.</p><button class="primary-button full" type="submit">테스트 결제 완료</button></form>`}

function activeFisher(data=db()){return data.session?.role==='fisher'&&data.fisherAccounts.find(a=>a.id===data.session.id)}
function activeBoat(data=db()){const account=activeFisher(data);return account&&data.boats.find(b=>b.id===account.boatId)}
function viewFisherEntry(){const data=db();if(activeFisher(data)){viewFisherHome();return}if(!data.fisherAccounts.length){viewFisherSignup();return}screen.innerHTML=back('어부')+`<section class="empty"><b>⚓</b><h2>어부 계정</h2><p>기존 어선으로 로그인하거나 새 어선을 등록하세요.</p><button class="primary-button full" data-go="fisher-login">기존 계정으로 로그인</button><button class="outline-button full" data-go="fisher-signup">새 계정 만들기</button></section>`}
function viewFisherSignup(){screen.innerHTML=back('어부 회원가입','role-select')+`<form class="form-card" id="fisher-signup-form"><label>어선 이름<input name="boatName" required placeholder="예: 바다희망호"></label><label>어부 이름<input name="fisherName" required placeholder="예: 홍길동"></label><label>비밀번호<input name="password" type="password" required placeholder="비밀번호 입력"></label><button class="primary-button full" type="submit">계정 및 어선 등록</button></form>`}
function viewFisherLogin(){const accounts=db().fisherAccounts;screen.innerHTML=back('어부 로그인','role-select')+`<form class="form-card" id="fisher-login-form"><label>어선 선택<select name="accountId">${accounts.map(a=>`<option value="${a.id}">${a.boatName}</option>`).join('')}</select></label><label>비밀번호<input name="password" type="password" required placeholder="비밀번호 입력"></label><button class="primary-button full" type="submit">로그인</button><button class="outline-button full" type="button" data-fisher-reset>비밀번호 재설정</button></form>`}
function viewFisherHome(){const b=activeBoat();if(!b){viewFisherEntry();return}screen.innerHTML=back('어부')+`<section class="fisher-banner"><small>등록 어선</small><h2>${b.icon||'⚓'} ${b.name}</h2><p>${b.fisher} 선장 · ${b.catch||'주요 어획물 미등록'}</p></section><section class="fisher-actions"><button class="action-card" data-go="write-log"><b>📝</b><span><strong>조업 일지 쓰기</strong>오늘의 어획과 조업 상황을 사진과 함께 기록하세요.</span><i>›</i></button><button class="action-card my" data-go="funds"><b>💰</b><span><strong>응원금 보기</strong>응원자가 보낸 누적 응원금을 확인하세요.</span><i>›</i></button><button class="action-card sell" data-go="sell"><b>🧺</b><span><strong>수산물 팔기</strong>산지 직송할 수산물을 등록하고 판매하세요.</span><i>›</i></button><button class="logout-button" data-logout>로그아웃</button></section>`}
function viewWriteLog(){screen.innerHTML=back('조업 일지 쓰기','fisher-home')+`<p class="subtitle">작성 날짜는 자동으로 기록되며, 등록 즉시 응원자 화면에도 반영됩니다.</p><form class="form-card" id="log-form"><label>오늘의 어획량 / 제목<input name="title" required placeholder="예: 고등어 30kg · 오징어 12kg"></label><label>조업 상황<textarea name="text" required placeholder="오늘의 날씨, 조업 위치, 어획 상황을 자유롭게 작성하세요."></textarea></label><label>조업 사진 <input name="photos" type="file" accept="image/*" multiple><small>여러 장 선택할 수 있습니다.</small></label><button class="primary-button full" type="submit">작성 완료</button></form>`}
function viewFunds(){const data=db(), b=activeBoat(data), amount=data.supports[b.id]||0;screen.innerHTML=back('응원금 보기','fisher-home')+`<section class="fund-card"><span>${b.name}에 도착한 누적 응원금</span><strong>${money(amount)}</strong><p>응원자가 보낸 금액이 저장 즉시 자동으로 반영됩니다.</p></section>`}
function viewSell(){const b=activeBoat();screen.innerHTML=back('수산물 팔기','fisher-home')+`<p class="subtitle">등록한 상품은 응원자 화면의 ‘수산물 받기’에 즉시 표시됩니다.</p><form class="form-card" id="product-form"><label>수산물 이름<input name="name" required placeholder="예: 손질 고등어 1kg"></label><div class="form-grid"><label>가격(원)<input name="price" type="number" min="0" required placeholder="15000"></label><label>수량<input name="quantity" type="number" min="1" required placeholder="10"></label></div><label>상품 설명<textarea name="description" required placeholder="상품 상태와 구성 등을 적어 주세요."></textarea></label><label>상품 사진<input name="photo" type="file" accept="image/*"><small>사진 1장을 등록할 수 있습니다.</small></label><button class="primary-button full" type="submit">🧺 판매 상품 등록</button></form><section class="mini-list"><h2>판매 목록 (${b.products.length})</h2>${b.products.map(p=>`<article class="sell-product-card"><span class="sell-product-image">${p.photo?`<img src="${p.photo}" alt="${p.name}">`:'🦪'}</span><span><strong>${p.name}</strong><small>${p.description||'산지 직송 상품'}</small><b>${money(p.price)} · ${p.quantity}개</b></span></article>`).join('')||'<p>아직 등록한 상품이 없습니다.</p>'}</section>`}
function postCard(p){const data=db(),key=data.session?`${data.session.role}-${data.session.id}`:'guest',liked=(p.likedBy||[]).includes(key);return `<article class="post-card"><div class="post-head"><span>${p.category==='recipe'?'🍳':p.category==='review'?'⭐':'💬'}</span><div><strong>${p.author}</strong><small>${p.date} · ${p.category==='recipe'?'수산물 레시피':p.category==='review'?'구매 후기':'소통 게시판'}</small></div>${p.rating?`<b>${'★'.repeat(p.rating)}${'☆'.repeat(5-p.rating)}</b>`:''}</div>${p.photo?`<img src="${p.photo}" alt="게시글 사진">`:''}<h3>${p.title}</h3><p>${p.content}</p><div class="post-actions"><button class="${liked?'liked':''}" data-like="${p.id}">${liked?'♥':'♡'} ${p.likes||0}</button><button data-post-detail="${p.id}">💬 ${(p.comments||[]).length}</button></div></article>`}
function ensureCommunityExamples(){const data=db(),examples=[{id:'example-talk-1',category:'talk',author:'바다지킴이',title:'오늘 통영 바다 날씨가 정말 좋네요',content:'조업 나가신 어민분들 모두 안전한 하루 보내세요. 신선한 소식 기다리고 있겠습니다!',rating:0,photo:'',likes:8,comments:[],date:'2026. 07. 29.'},{id:'example-talk-2',category:'talk',author:'제철해산물러버',title:'처음 응원한 어선의 조업일지를 봤어요',content:'출항부터 선별까지 과정을 볼 수 있어서 더 믿음이 갑니다. 다음에는 직송도 신청해 보려고요.',rating:0,photo:'',likes:6,comments:[],date:'2026. 07. 29.'},{id:'example-recipe-1',category:'recipe',author:'바다 한 상',title:'고등어 소금구이, 바삭하게 굽는 법',content:'고등어 표면의 물기를 닦고 소금을 살짝 뿌린 뒤, 중불에서 껍질 쪽부터 노릇하게 구워 주세요.',rating:0,photo:'',likes:17,comments:[],date:'2026. 07. 29.'},{id:'example-recipe-2',category:'recipe',author:'집밥어부',title:'문어 초무침 한 접시',content:'삶은 문어에 오이와 양파를 더하고 초고추장, 식초, 참기름을 넣으면 여름철 입맛을 돋우는 반찬이 됩니다.',rating:0,photo:'',likes:14,comments:[],date:'2026. 07. 29.'},{id:'example-review-1',category:'review',author:'통영을좋아해',title:'전갱이 직송 구매 후기',content:'아이스팩 포장이 꼼꼼했고 비린내 없이 정말 신선했어요. 구이와 조림 모두 만족입니다.',rating:5,photo:'',likes:11,comments:[],date:'2026. 07. 29.'},{id:'example-review-2',category:'review',author:'오늘도한상',title:'갈치 선물했어요',content:'부모님 댁으로 보냈는데 크기도 좋고 손질이 깔끔하다고 칭찬받았습니다.',rating:4,photo:'',likes:9,comments:[],date:'2026. 07. 29.'}];examples.forEach(p=>{if(!data.posts.some(x=>x.id===p.id))data.posts.push(p)});save(data);return data}
function viewCommunity(tab='talk'){const data=ensureCommunityExamples(),posts=data.posts.filter(p=>p.category===tab).slice().reverse();screen.innerHTML=back('커뮤니티')+`<p class="subtitle">어민과 소비자가 함께 만드는 바다 이야기입니다.</p><div class="community-tabs"><button class="${tab==='talk'?'selected':''}" data-community-tab="talk">💬 소통</button><button class="${tab==='recipe'?'selected':''}" data-community-tab="recipe">🍳 레시피</button><button class="${tab==='review'?'selected':''}" data-community-tab="review">⭐ 후기</button></div><button class="write-post" data-write-post="${tab}">✏️ ${tab==='recipe'?'레시피':'게시글'} 작성</button><section class="post-list">${posts.length?posts.map(postCard).join(''):`<section class="empty"><b>${tab==='recipe'?'🍳':tab==='review'?'⭐':'💬'}</b><h2>아직 게시글이 없어요</h2><p>첫 번째 이야기를 남겨 보세요.</p></section>`}</section>`}
function communityAuthor(data=db()){if(data.session?.role==='supporter')return data.supporterAccounts.find(a=>a.id===data.session.id)?.username||'';if(data.session?.role==='fisher')return data.fisherAccounts.find(a=>a.id===data.session.id)?.boatName||'';return ''}
function viewWritePost(category){const label=category==='recipe'?'수산물 레시피':category==='review'?'구매 후기':'소통 게시글',author=communityAuthor();screen.innerHTML=back(`${label} 작성`,'community')+`<form class="form-card" id="post-form"><input type="hidden" name="category" value="${category}"><label>작성자<input name="author" required value="${author}" placeholder="닉네임을 입력하세요" ${author?'readonly':''}></label><label>제목<input name="title" required placeholder="제목을 입력하세요"></label>${category==='review'?`<label>별점<select name="rating"><option value="5">★★★★★ (5점)</option><option value="4">★★★★☆ (4점)</option><option value="3">★★★☆☆ (3점)</option><option value="2">★★☆☆☆ (2점)</option><option value="1">★☆☆☆☆ (1점)</option></select></label>`:''}<label>${category==='recipe'?'레시피 내용':'내용'}<textarea name="content" required placeholder="${category==='recipe'?'재료와 조리 방법을 자유롭게 작성하세요.':'조업 이야기, 응원 메시지, 질문을 자유롭게 남겨 주세요.'}"></textarea></label><label>사진<input name="photo" type="file" accept="image/*"><small>사진 1장을 함께 올릴 수 있습니다.</small></label><button class="primary-button full" type="submit">등록하기</button></form>`}
function viewPostDetail(id){const p=db().posts.find(x=>x.id===id),author=communityAuthor();screen.innerHTML=back('게시글', 'community')+`<section class="post-list">${postCard(p)}</section><section class="comment-box"><h2>댓글 ${(p.comments||[]).length}</h2>${(p.comments||[]).map(c=>`<article><strong>${c.author}</strong><small>${c.date}</small><p>${c.text}</p></article>`).join('')||'<p class="no-comment">첫 댓글을 남겨 보세요.</p>'}<form id="comment-form"><input type="hidden" name="postId" value="${p.id}"><input name="author" required value="${author}" placeholder="닉네임" ${author?'readonly':''}><input name="text" required placeholder="댓글을 입력하세요"><button type="submit">등록</button></form></section>`}

async function filesToData(files){return Promise.all([...files].map(f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)})))}
screen.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;const go=t.dataset.go;if(go==='start')viewHome();if(go==='community')viewCommunity();if(go==='role-select')viewRoleSelect();if(go==='support-home')viewSupportHome();if(go==='support-entry')viewSupportEntry();if(go==='support-login')viewSupportLogin();if(go==='support-signup')viewSupportSignup();if(go==='boats')viewBoats();if(go==='my-boats')viewMyBoats();if(go==='my-orders')viewMyOrders();if(go==='fisher-entry')viewFisherEntry();if(go==='fisher-home')viewFisherHome();if(go==='fisher-login')viewFisherLogin();if(go==='fisher-signup')viewFisherSignup();if(go==='write-log')viewWriteLog();if(go==='funds')viewFunds();if(go==='sell')viewSell();if(t.dataset.productDetail){const [b,p]=t.dataset.productDetail.split('|');viewProductDetail(b,p)}if(t.dataset.orderStart){const [b,p]=t.dataset.orderStart.split('|');viewOrderForm(b,p)}if(t.dataset.communityTab)viewCommunity(t.dataset.communityTab);if(t.dataset.writePost)viewWritePost(t.dataset.writePost);if(t.dataset.postDetail)viewPostDetail(t.dataset.postDetail);if(t.dataset.like){const data=db(),p=data.posts.find(x=>x.id===t.dataset.like),key=data.session?`${data.session.role}-${data.session.id}`:'guest';p.likedBy??=[];if(p.likedBy.includes(key)){p.likedBy=p.likedBy.filter(x=>x!==key);p.likes=Math.max(0,(p.likes||0)-1)}else{p.likedBy.push(key);p.likes=(p.likes||0)+1}save(data);viewCommunity(p.category)}if(t.hasAttribute('data-logout')){const data=db();data.session=null;save(data);toast('로그아웃되었습니다.');viewRoleSelect()}if(t.dataset.support)openSupport(t.dataset.support);if(t.dataset.detail)viewSupportDetail(t.dataset.detail);if(t.dataset.log)viewLogs(t.dataset.log,t.dataset.back||'support-detail');if(t.dataset.publicLog)viewLogs(t.dataset.publicLog,'boats');if(t.dataset.products)viewProducts(t.dataset.products);if(t.dataset.publicProducts)viewProducts(t.dataset.publicProducts,'boats')});
screen.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=db(), values=new FormData(form);if(form.id==='support-signup-form'){const username=values.get('username').trim();if(data.supporterAccounts.some(a=>a.username===username)){toast('이미 사용 중인 아이디입니다.');return}const id='supporter-'+Date.now();data.supporterAccounts.push({id,username,password:values.get('password')});data.session={role:'supporter',id};save(data);toast('응원자 회원가입이 완료되었습니다.');viewSupportHome();return}if(form.id==='support-login-form'){const a=data.supporterAccounts.find(a=>a.id===values.get('accountId'));if(!a||a.password!==values.get('password')){toast('비밀번호가 올바르지 않습니다.');return}data.session={role:'supporter',id:a.id};save(data);viewSupportHome();return}if(form.id==='fisher-signup-form'){const boatName=values.get('boatName').trim(),fisherName=values.get('fisherName').trim();if(data.fisherAccounts.some(a=>a.boatName===boatName)||data.boats.some(b=>b.name===boatName)){toast('이미 사용 중인 어선 이름입니다.');return}const accountId='fisher-'+Date.now(),boatId='boat-'+Date.now();data.boats.push({id:boatId,ownerId:accountId,name:boatName,fisher:fisherName,catch:'어획물 정보 미등록',port:'내 등록 어선',icon:'⚓',logs:[],products:[]});data.fisherAccounts.push({id:accountId,boatId,boatName,fisherName,password:values.get('password')});data.session={role:'fisher',id:accountId};save(data);toast('어부 회원가입이 완료되었습니다.');viewFisherHome();return}if(form.id==='fisher-login-form'){const a=data.fisherAccounts.find(a=>a.id===values.get('accountId'));if(!a||a.password!==values.get('password')){toast('비밀번호가 올바르지 않습니다.');return}data.session={role:'fisher',id:a.id};save(data);viewFisherHome();return}if(form.id==='post-form'){const files=form.elements.photo.files,photo=files.length?(await filesToData(files))[0]:'';data.posts.push({id:'post-'+Date.now(),category:values.get('category'),author:values.get('author'),title:values.get('title'),content:values.get('content'),rating:Number(values.get('rating')||0),photo,likes:0,comments:[],date:today()});save(data);toast('게시글이 등록되었습니다.');viewCommunity(values.get('category'));return}if(form.id==='comment-form'){const p=data.posts.find(x=>x.id===values.get('postId'));p.comments.push({author:values.get('author'),text:values.get('text'),date:today()});save(data);toast('댓글이 등록되었습니다.');viewPostDetail(p.id);return}if(form.id==='log-form'){const b=activeBoat(data),photos=await filesToData(form.elements.photos.files);b.logs.push({date:today(),title:values.get('title'),text:values.get('text'),photos});save(data);toast('조업 일지가 등록되었습니다.');viewFisherHome()}if(form.id==='product-form'){const b=activeBoat(data),photoFiles=form.elements.photo.files,photo=photoFiles.length?(await filesToData(photoFiles))[0]:'';b.products.push({id:'product-'+Date.now(),name:values.get('name'),price:Number(values.get('price')),quantity:Number(values.get('quantity')),description:values.get('description'),photo});save(data);toast('판매 상품이 등록되었습니다.');viewSell()}});
modalLayer.addEventListener('click',e=>{if(e.target===modalLayer||e.target.closest('[data-close]')){modalLayer.hidden=true;return}const t=e.target.closest('[data-confirm-support]');if(!t)return;const amount=Number(document.querySelector('#support-amount').value),help=document.querySelector('#amount-help');if(!amount||amount<10000){help.textContent='응원금은 10,000원 이상 입력해 주세요.';return}const data=db(),id=t.dataset.confirmSupport,user=activeSupporter(data);data.supports[id]=(data.supports[id]||0)+amount;data.supporterSupports[user.id]??={};data.supporterSupports[user.id][id]=(data.supporterSupports[user.id][id]||0)+amount;save(data);modalLayer.hidden=true;toast(`${boat(id).name} 응원이 완료됐어요.`);viewMyBoats()});
new MutationObserver(()=>{screen.classList.remove('screen-in');requestAnimationFrame(()=>screen.classList.add('screen-in'))}).observe(screen,{childList:true});
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY)viewHome()});
document.querySelector('#home-button').addEventListener('click',viewHome);viewHome();
screen.addEventListener('submit',e=>{const form=e.target;if(form.id!=='order-form'&&form.id!=='payment-form')return;e.preventDefault();const data=db(),values=new FormData(form);if(form.id==='order-form'){viewPayment({boatId:values.get('boatId'),productId:values.get('productId'),quantity:Number(values.get('quantity')),recipient:values.get('recipient'),phone:values.get('phone'),address:values.get('address'),request:values.get('request')});return}const draft=JSON.parse(sessionStorage.getItem('fishFunding.orderDraft')),user=activeSupporter(data),b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId),total=p.price*draft.quantity,payment=values.get('payment');if(draft.quantity>p.quantity){toast('재고 수량이 부족합니다.');return}if(payment==='wallet'&&user.wallet<total){toast('포인트 잔액이 부족합니다.');return}if(payment==='wallet')user.wallet-=total;p.quantity-=draft.quantity;const labels={reservation:'예약 구매',card:'카드 결제',transfer:'계좌이체',wallet:'포인트 결제'};data.orders.push({id:'order-'+Date.now(),supporterId:user.id,fisherId:b.ownerId||null,boatId:b.id,productId:p.id,productName:p.name,quantity:draft.quantity,total,payment,paymentLabel:labels[payment],status:payment==='transfer'?'결제 대기':payment==='reservation'?'상품 준비 중':'결제 완료',recipient:draft.recipient,phone:draft.phone,address:draft.address,request:draft.request,date:today()});save(data);sessionStorage.removeItem('fishFunding.orderDraft');toast('주문과 테스트 결제가 완료되었습니다.');viewMyOrders()});
function viewFisherReset(){screen.innerHTML=back('어부 비밀번호 재설정','fisher-entry')+`<p class="subtitle">등록한 어선 이름과 어부 이름을 정확히 입력한 뒤 새 비밀번호를 설정해 주세요.</p><form class="form-card" id="fisher-reset-form"><label>어선 이름<input name="boatName" required placeholder="등록한 어선 이름"></label><label>어부 이름<input name="fisherName" required placeholder="등록한 어부 이름"></label><label>새 비밀번호<input name="password" type="password" required placeholder="새 비밀번호 입력"></label><button class="primary-button full" type="submit">비밀번호 재설정</button></form>`}
screen.addEventListener('click',e=>{const t=e.target.closest('[data-fisher-reset]');if(t)viewFisherReset()});
screen.addEventListener('submit',e=>{if(e.target.id!=='fisher-reset-form')return;e.preventDefault();const values=new FormData(e.target),data=db(),boatName=values.get('boatName').trim(),fisherName=values.get('fisherName').trim(),boat=data.boats.find(b=>b.name===boatName&&b.fisher===fisherName),account=boat&&data.fisherAccounts.find(a=>a.boatId===boat.id);if(!account){toast('어선 이름 또는 어부 이름이 일치하지 않습니다.');return}account.password=values.get('password');save(data);toast('비밀번호가 재설정되었습니다.');viewFisherLogin()});
function purchasePolicy(data,draft,user,b,p){const now=new Date(),todayKey=now.toDateString(),pastWeek=Date.now()-7*86400000,orders=data.orders||[],sameProduct=orders.filter(o=>o.supporterId===user.id&&o.productId===p.id),todayOrders=sameProduct.filter(o=>new Date(o.createdAt||o.date).toDateString()===todayKey),weekOrders=sameProduct.filter(o=>new Date(o.createdAt||o.date).getTime()>=pastWeek),limit=p.maxPerBuyer||2,addressToday=orders.filter(o=>o.address===draft.address&&new Date(o.createdAt||o.date).toDateString()===todayKey).length;let review=[];if(draft.quantity>limit)return {blocked:`1인 최대 구매 수량은 ${limit}${p.unit||'개'}입니다.`};if(todayOrders.length)return {blocked:'동일 상품은 계정당 하루 1회만 구매할 수 있습니다.'};if(weekOrders.length>=2)return {blocked:'동일 상품은 일주일에 최대 2회까지 구매할 수 있습니다.'};if(addressToday>=10)review.push('동일 배송지의 일일 주문이 10건 이상입니다.');const supported=(data.supporterSupports[user.id]?.[b.id]||0)>0;return {review,priority:supported?'응원자 우선 구매':'일반 구매'}}
screen.addEventListener('submit',e=>{const form=e.target;if(form.id!=='payment-form')return;e.preventDefault();e.stopImmediatePropagation();const data=db(),draft=JSON.parse(sessionStorage.getItem('fishFunding.orderDraft')),user=activeSupporter(data),b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId),policy=purchasePolicy(data,draft,user,b,p);if(policy.blocked){toast(policy.blocked);return}const values=new FormData(form),total=p.price*draft.quantity,payment=values.get('payment');if(draft.quantity>p.quantity){toast('재고 수량이 부족합니다.');return}if(payment==='wallet'&&user.wallet<total){toast('포인트 잔액이 부족합니다.');return}if(payment==='wallet')user.wallet-=total;p.quantity-=draft.quantity;const labels={reservation:'예약 구매',card:'카드 결제',transfer:'계좌이체',wallet:'포인트 결제'},limited=p.quantity<=3;const order={id:'order-'+Date.now(),supporterId:user.id,fisherId:b.ownerId||null,boatId:b.id,productId:p.id,productName:p.name,quantity:draft.quantity,total,payment,paymentLabel:labels[payment],status:limited?'대기열 대기':payment==='transfer'?'결제 대기':payment==='reservation'?'상품 준비 중':'결제 완료',recipient:draft.recipient,phone:draft.phone,address:draft.address,request:draft.request,date:today(),createdAt:new Date().toISOString(),priority:policy.priority,review:policy.review};data.orders.push(order);if(policy.review.length){data.adminAlerts??=[];data.adminAlerts.push({id:'alert-'+Date.now(),orderId:order.id,message:policy.review.join(' '),status:'검토 대기',date:today()})}save(data);sessionStorage.removeItem('fishFunding.orderDraft');toast(limited?'한정 수량 대기열에 참여했습니다.':'주문과 테스트 결제가 완료되었습니다.');viewMyOrders()},true);
(()=>{const onboard=document.querySelector('#onboarding');if(!onboard||localStorage.getItem('fishFunding.tutorialDone')==='true'){onboard?.classList.add('hidden');return}const slides=[{step:'01',title:'바다의 하루를<br>가까이에서 만나보세요',text:'오늘의 날씨와 조업 현황을 보고,<br>신선한 바다 이야기를 함께 나눠요.',boat:'⛵',mascot:'🐟',sun:'☀️'},{step:'02',title:'마음에 드는 어선을<br>응원해 보세요',text:'조업비를 응원하고 어선의 타임라인을<br>따라가며 바다의 과정을 확인해요.',boat:'⚓',mascot:'😮',sun:'🌊'},{step:'03',title:'신선함은 가장 빠르게<br>식탁으로 보내요',text:'오늘 잡은 수산물을 산지에서 받아보고,<br>커뮤니티에서 바다 이야기를 이어가요.',boat:'🧺',mascot:'😄',sun:'✨'}];let step=0;const render=()=>{const s=slides[step];onboard.className=`onboarding step-${step+1}`;document.querySelector('#tutorial-step').textContent=s.step;document.querySelector('#tutorial-title').innerHTML=s.title;document.querySelector('#tutorial-description').innerHTML=s.text;document.querySelector('.tutorial-boat').textContent=s.boat;document.querySelector('.tutorial-mascot').textContent=s.mascot;document.querySelector('.tutorial-sun').textContent=s.sun;document.querySelectorAll('#tutorial-dots i').forEach((dot,i)=>dot.classList.toggle('active',i===step));document.querySelector('#tutorial-next').innerHTML=step===2?'피시 펀딩 시작 <span>→</span>':'다음 <span>→</span>'};const close=()=>{localStorage.setItem('fishFunding.tutorialDone','true');onboard.classList.add('hidden')};document.querySelector('#tutorial-next').addEventListener('click',()=>{if(step===2)close();else{step++;render()}});document.querySelector('#tutorial-skip').addEventListener('click',close);render()})();
(()=>{const icons=[['🛥️','🐬','☀️'],['⚓','💙','🌊'],['🧺','🐟','✨']];const tune=()=>{const step=Number(document.querySelector('#tutorial-step')?.textContent||'01')-1,icon=icons[step]||icons[0];const boat=document.querySelector('.tutorial-boat'),mascot=document.querySelector('.tutorial-mascot'),sun=document.querySelector('.tutorial-sun');if(boat)boat.textContent=icon[0];if(mascot)mascot.textContent=icon[1];if(sun)sun.textContent=icon[2]};tune();document.querySelector('#tutorial-next')?.addEventListener('click',()=>setTimeout(tune,0));})()
screen.addEventListener('submit',e=>{const form=e.target;if(form.id!=='support-order-form'&&form.id!=='support-payment-form')return;e.preventDefault();e.stopImmediatePropagation();const data=db(),values=new FormData(form);if(form.id==='support-order-form'){const username=values.get('username').trim(),account=data.supporterAccounts.find(a=>a.username===username);if(!account||account.password!==values.get('password')){toast('응원자 아이디 또는 비밀번호가 올바르지 않습니다.');return}const amount=Number(values.get('amount'));if(amount<10000){toast('응원금은 10,000원 이상 입력해 주세요.');return}viewSupportPayment({boatId:values.get('boatId'),supporterId:account.id,amount});return}const draft=JSON.parse(sessionStorage.getItem('fishFunding.supportDraft')),payment=values.get('payment');if(payment==='card'&&(!String(values.get('cardNumber')).trim()||!String(values.get('cardInfo')).trim())){toast('테스트 카드 정보를 입력해 주세요.');return}data.supportPayments??=[];data.supports[draft.boatId]=(data.supports[draft.boatId]||0)+draft.amount;data.supporterSupports[draft.supporterId]??={};data.supporterSupports[draft.supporterId][draft.boatId]=(data.supporterSupports[draft.supporterId][draft.boatId]||0)+draft.amount;data.supportPayments.push({id:'support-'+Date.now(),boatId:draft.boatId,supporterId:draft.supporterId,amount:draft.amount,payment,paymentLabel:payment==='card'?'카드 결제':'계좌이체',status:payment==='card'?'결제 완료':'입금 확인 대기',date:today()});save(data);sessionStorage.removeItem('fishFunding.supportDraft');toast(payment==='card'?'응원 결제가 완료되었습니다. 감사합니다!':'응원 주문이 접수되었습니다. 입금 확인을 기다려 주세요.');viewMyBoats()},true);
(()=>{const data=db(),harbor=data.boats.find(b=>b.id==='safe-harbor');if(harbor&&harbor.icon!=='⚓'){harbor.icon='⚓';save(data)}})();
const POINTS_PER_THOUSAND=100,REWARD_PER_THOUSAND=20;
const pointCost=won=>Math.ceil(won/1000)*POINTS_PER_THOUSAND;
const pointReward=won=>Math.floor(won/1000)*REWARD_PER_THOUSAND;
function addPointHistory(data,supporterId,amount,reason){data.pointHistory??=[];data.pointHistory.push({id:'point-'+Date.now()+Math.random(),supporterId,amount,reason,date:today()})}
function viewPayment(draft){const b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId),total=p.price*draft.quantity,user=activeSupporter(),cost=pointCost(total),reward=pointReward(total);sessionStorage.setItem('fishFunding.orderDraft',JSON.stringify(draft));screen.innerHTML=back('결제 방식','support-home')+`<section class="order-summary"><strong>${p.name} × ${draft.quantity}</strong><span>결제 금액 <b>${money(total)}</b></span></section><form class="form-card" id="payment-form-v2"><label><input type="radio" name="payment" value="reservation"> 예약 구매 <small>다음 조업 후 수산물을 확보해 순차 배송합니다.</small></label><label><input type="radio" name="payment" value="card" checked> 카드 결제 <select name="card"><option>테스트 신한카드</option><option>테스트 국민카드</option><option>테스트 현대카드</option></select></label><label><input type="radio" name="payment" value="transfer"> 계좌이체 <small>피시 펀딩 · 1002-000-123456 (테스트 계좌)</small></label><label><input type="radio" name="payment" value="wallet"> 포인트 결제 <small>사용 ${cost.toLocaleString()}P · 현재 ${user.wallet.toLocaleString()}P · 구매 적립 +${reward.toLocaleString()}P</small></label><p class="policy-note">포인트는 1,000원당 100P로 사용되며, 구매 시 1,000원당 20P가 적립됩니다.</p><button class="primary-button full" type="submit">테스트 결제 완료</button></form>`}
function viewMyOrders(){const data=db(),user=activeSupporter(data),orders=data.orders.filter(o=>o.supporterId===user.id).slice().reverse();screen.innerHTML=back('구매 내역','support-home')+(orders.length?`<section class="order-list">${orders.map(o=>`<article><strong>${o.productName}</strong><span>${o.status} · ${money(o.total)}</span><small>${o.date} · ${o.paymentLabel}${o.pointDelta?` · 포인트 ${o.pointDelta>0?'+':''}${o.pointDelta.toLocaleString()}P`:''}</small></article>`).join('')}</section>`:`<section class="empty"><b>📦</b><h2>구매 내역이 없어요</h2><p>산지 직송 수산물을 주문해 보세요.</p></section>`)}
screen.addEventListener('submit',e=>{const form=e.target;if(form.id!=='support-signup-form'&&form.id!=='support-login-form')return;e.preventDefault();e.stopImmediatePropagation();const data=db(),values=new FormData(form);if(form.id==='support-signup-form'){const username=values.get('username').trim();if(data.supporterAccounts.some(a=>a.username===username)){toast('이미 사용 중인 아이디입니다.');return}const id='supporter-'+Date.now();data.supporterAccounts.push({id,username,password:values.get('password'),wallet:20000});data.session={role:'supporter',id};save(data);toast('응원자 회원가입이 완료되었습니다. 기본 20,000P가 지급되었어요.');viewSupportHome();return}const account=data.supporterAccounts.find(a=>a.id===values.get('accountId'));if(!account||account.password!==values.get('password')){toast('비밀번호가 올바르지 않습니다.');return}account.wallet=(account.wallet??20000)+500;addPointHistory(data,account.id,500,'로그인 보너스');data.session={role:'supporter',id:account.id};save(data);toast('로그인 보너스 500P가 지급되었습니다.');viewSupportHome()},true);
screen.addEventListener('submit',e=>{const form=e.target;if(form.id!=='payment-form-v2')return;e.preventDefault();e.stopImmediatePropagation();const data=db(),draft=JSON.parse(sessionStorage.getItem('fishFunding.orderDraft')),user=activeSupporter(data),b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId),policy=purchasePolicy(data,draft,user,b,p);if(policy.blocked){toast(policy.blocked);return}if(draft.quantity>p.quantity){toast('재고 수량이 부족합니다.');return}const payment=new FormData(form).get('payment'),total=p.price*draft.quantity,cost=pointCost(total),reward=pointReward(total);if(payment==='wallet'&&user.wallet<cost){toast(`포인트가 부족합니다. ${cost.toLocaleString()}P가 필요해요.`);return}let pointDelta=reward;if(payment==='wallet')pointDelta-=cost;user.wallet+=pointDelta;p.quantity-=draft.quantity;const labels={reservation:'예약 구매',card:'카드 결제',transfer:'계좌이체',wallet:'포인트 결제'},limited=p.quantity<=3;const order={id:'order-'+Date.now(),supporterId:user.id,fisherId:b.ownerId||null,boatId:b.id,productId:p.id,productName:p.name,quantity:draft.quantity,total,payment,paymentLabel:labels[payment],status:limited?'대기열 대기':payment==='transfer'?'결제 대기':payment==='reservation'?'상품 준비 중':'결제 완료',recipient:draft.recipient,phone:draft.phone,address:draft.address,request:draft.request,date:today(),createdAt:new Date().toISOString(),priority:policy.priority,review:policy.review,pointDelta,pointCost:payment==='wallet'?cost:0,pointReward:reward};data.orders.push(order);if(pointDelta)addPointHistory(data,user.id,pointDelta,payment==='wallet'?`포인트 결제 · ${p.name}`:`구매 적립 · ${p.name}`);if(policy.review.length){data.adminAlerts??=[];data.adminAlerts.push({id:'alert-'+Date.now(),orderId:order.id,message:policy.review.join(' '),status:'검토 대기',date:today()})}save(data);sessionStorage.removeItem('fishFunding.orderDraft');toast(`주문이 완료되었습니다. 포인트 ${pointDelta>0?'+':''}${pointDelta.toLocaleString()}P`);viewMyOrders()},true);
(()=>{const data=db();let changed=false;data.supporterAccounts.forEach(account=>{const hasHistory=data.pointHistory?.some(item=>item.supporterId===account.id);if(account.wallet===50000&&!hasHistory){account.wallet=20000;changed=true}});if(changed)save(data)})();
function ensureCommunityExamples(){const data=db(),examples=[{id:'welcome-talk',category:'talk',author:'피시 펀딩 운영팀',title:'피시 펀딩 커뮤니티에 오신 것을 환영합니다',content:'조업 이야기, 바다에 대한 질문, 응원 메시지를 자유롭게 나눠 주세요. 서로의 오늘을 응원하는 따뜻한 공간입니다.',rating:0,photo:'',likes:12,comments:[{author:'바다지킴이',text:'어민분들의 안전한 조업을 응원합니다!',date:'2026. 07. 28.'},{author:'통영식탁',text:'조업 일지를 보니 다음 직송도 기대돼요.',date:'2026. 07. 29.'},{author:'오늘의바다',text:'안전이 제일입니다. 늘 고맙습니다.',date:'2026. 07. 29.'}],date:'2026. 07. 28.'},{id:'example-talk-1',category:'talk',author:'바다지킴이',title:'오늘 통영 바다 날씨가 정말 좋네요',content:'조업 나가신 어민분들 모두 안전한 하루 보내세요. 신선한 소식 기다리고 있겠습니다!',rating:0,photo:'',likes:8,comments:[{author:'푸른바다호',text:'응원 덕분에 힘내서 출항했습니다. 감사합니다!',date:'2026. 07. 29.'}],date:'2026. 07. 29.'},{id:'example-talk-2',category:'talk',author:'제철해산물러버',title:'처음 응원한 어선의 조업일지를 봤어요',content:'출항부터 선별까지 과정을 볼 수 있어서 더 믿음이 갑니다. 다음에는 직송도 신청해 보려고요.',rating:0,photo:'',likes:6,comments:[{author:'바다초보',text:'저도 조업 타임라인 보는 재미에 매일 들어와요.',date:'2026. 07. 29.'},{author:'집밥어부',text:'궁금한 점은 언제든 게시판에 남겨 주세요.',date:'2026. 07. 29.'},{author:'바다러버',text:'직송 받은 고등어도 정말 싱싱했어요.',date:'2026. 07. 29.'},{author:'제철해산물러버',text:'추천 감사합니다. 이번 주에 주문해 볼게요!',date:'2026. 07. 29.'}],date:'2026. 07. 29.'},{id:'welcome-recipe',category:'recipe',author:'통영 바다식탁',title:'버섯 듬뿍 해산물 오일파스타',content:'재료: 스파게티면, 생굴 또는 새우, 버섯, 마늘, 올리브유, 레몬. ① 면은 1분 짧게 삶고 면수 반 컵을 남겨요. ② 팬에 올리브유와 마늘을 약불에서 볶습니다. ③ 버섯을 노릇하게 익힌 뒤 해산물을 1분만 익혀요. ④ 면과 면수, 후추를 넣어 섞고 마지막에 레몬즙을 더하면 완성입니다.',rating:0,photo:'assets/recipe-seafood-pasta.png',likes:28,comments:[{author:'굴러버',text:'마지막에 넣는다는 팁이 정말 유용해요.',date:'2026. 07. 28.'},{author:'파스타초보',text:'면수 양까지 적어 주셔서 성공했습니다!',date:'2026. 07. 29.'}],date:'2026. 07. 28.'},{id:'example-recipe-1',category:'recipe',author:'바다 한 상',title:'고등어 소금구이, 바삭하게 굽는 법',content:'고등어 표면의 물기를 닦고 소금을 살짝 뿌린 뒤, 중불에서 껍질 쪽부터 노릇하게 구워 주세요. 마지막에 레몬즙을 살짝 더하면 깔끔합니다.',rating:0,photo:'assets/recipe-mackerel-grill.png',likes:17,comments:[{author:'한끼뚝딱',text:'껍질부터 굽는 방법으로 하니 정말 바삭해요.',date:'2026. 07. 29.'}],date:'2026. 07. 29.'},{id:'example-recipe-2',category:'recipe',author:'집밥어부',title:'매콤한 해산물 초무침',content:'문어와 오징어, 채소를 먹기 좋게 썰어 초고추장, 식초, 참기름으로 가볍게 무쳐 주세요. 깨를 뿌리면 여름철 입맛을 돋우는 한 접시가 됩니다.',rating:0,photo:'assets/recipe-spicy-seafood.png',likes:14,comments:[{author:'매콤러버',text:'양념 비율이 궁금했는데 딱 좋네요.',date:'2026. 07. 29.'},{author:'집밥초보',text:'오이는 소금에 살짝 절여 넣으니 물이 덜 생겼어요.',date:'2026. 07. 29.'},{author:'바다식탁',text:'남은 양념에 소면을 비벼도 맛있습니다.',date:'2026. 07. 29.'}],date:'2026. 07. 29.'},{id:'welcome-review',category:'review',author:'신선한식탁',title:'산지 직송 참돔 후기',content:'포장을 열자마자 신선함이 느껴졌어요. 가족들과 맑은탕으로 맛있게 먹었습니다. 다만 손질 옵션이 더 다양하면 좋겠습니다.',rating:4,photo:'',likes:19,comments:[{author:'푸른바다호',text:'소중한 의견 감사합니다. 손질 옵션을 검토하겠습니다.',date:'2026. 07. 29.'}],date:'2026. 07. 28.'},{id:'example-review-1',category:'review',author:'통영을좋아해',title:'전갱이 직송 구매 후기',content:'아이스팩 포장이 꼼꼼했고 비린내 없이 정말 신선했어요. 구이와 조림 모두 만족입니다.',rating:5,photo:'',likes:11,comments:[{author:'전갱이팬',text:'조림용으로도 괜찮다니 다음에 주문해 볼게요.',date:'2026. 07. 29.'},{author:'통영을좋아해',text:'살이 단단해서 조림에도 잘 어울렸어요.',date:'2026. 07. 29.'}],date:'2026. 07. 29.'},{id:'example-review-2',category:'review',author:'오늘도한상',title:'갈치 선물했어요',content:'부모님 댁으로 보냈는데 크기도 좋고 손질이 깔끔하다고 칭찬받았습니다. 배송 예정 시간 안내가 조금 더 빨랐으면 좋겠어요.',rating:3,photo:'',likes:9,comments:[{author:'해맞이호',text:'배송 안내 관련 의견을 반영해 더 빠르게 안내드릴게요.',date:'2026. 07. 29.'},{author:'오늘도한상',text:'답변 감사합니다. 다음 주문도 기대할게요.',date:'2026. 07. 29.'},{author:'갈치좋아',text:'솔직한 후기라 주문할 때 참고가 됩니다.',date:'2026. 07. 29.'}],date:'2026. 07. 29.'}];examples.forEach(post=>{const old=data.posts.find(item=>item.id===post.id);if(old)Object.assign(old,post);else data.posts.push(post)});save(data);return data}
function viewSupportSignup(){screen.innerHTML=back('응원자 회원가입','role-select')+`<form class="form-card" id="support-signup-form-v2"><label>아이디<input name="username" required placeholder="아이디 입력"></label><label>비밀번호<input name="password" type="password" required placeholder="비밀번호 입력"></label><button class="primary-button full" type="submit">회원가입</button></form>`}
screen.addEventListener('submit',e=>{if(e.target.id!=='support-signup-form-v2')return;e.preventDefault();const data=db(),values=new FormData(e.target),username=values.get('username').trim();if(data.supporterAccounts.some(account=>account.username===username)){toast('이미 사용 중인 아이디입니다.');return}const id='supporter-'+Date.now();data.supporterAccounts.push({id,username,password:values.get('password'),wallet:2000});data.session={role:'supporter',id};save(data);toast('응원자 회원가입이 완료되었습니다. 기본 2,000P가 지급되었어요.');viewSupportHome()},true);
(()=>{const data=db();let changed=false;data.supporterAccounts.forEach(account=>{const hasHistory=data.pointHistory?.some(item=>item.supporterId===account.id);if(account.wallet===20000&&!hasHistory){account.wallet=2000;changed=true}});if(changed)save(data)})();
function markBlueSeaVideo(){document.querySelectorAll('.feed-card').forEach(card=>{if(card.querySelector('.feed-head strong')?.textContent!=='푸른바다호'||card.querySelector('.video-badge'))return;card.classList.add('has-video');card.insertAdjacentHTML('beforeend','<span class="video-badge" aria-label="영상처럼 표현한 조업 기록">▶</span>')})}
new MutationObserver(markBlueSeaVideo).observe(screen,{childList:true,subtree:true});
markBlueSeaVideo();
(()=>{const data=db();if(!data.posts.some(post=>post.id==='example-review-3')){data.posts.push({id:'example-review-3',category:'review',author:'배송기다림',title:'상품은 괜찮았지만 배송이 아쉬웠어요',content:'상품 자체는 나쁘지 않았지만 배송 안내가 늦었고 도착 시간이 많이 밀렸습니다. 다음에는 배송 상황을 더 빠르게 알려주시면 좋겠습니다.',rating:1,photo:'',likes:3,comments:[{author:'피시 펀딩 운영팀',text:'불편을 드려 죄송합니다. 배송 안내 절차를 개선하겠습니다.',date:'2026. 07. 29.'}],date:'2026. 07. 29.'});save(data)}})();
(()=>{const data=db(),post=data.posts.find(item=>item.id==='example-review-3');if(post){Object.assign(post,{author:'바다손님',title:'배송 상태 안내가 늦어 불만족스러웠어요',content:'배송 예정일이 지나서야 안내를 받았고, 문의 답변도 늦었습니다. 상품 자체보다 배송 과정이 불편해서 다음 주문은 고민해 보려 합니다.',rating:1,comments:[{author:'피시 펀딩 운영팀',text:'불편을 드려 죄송합니다. 배송 안내와 문의 응답 과정을 점검하겠습니다.',date:'2026. 07. 29.'},{author:'바다손님',text:'빠른 개선이 있었으면 좋겠습니다.',date:'2026. 07. 29.'}]});save(data)}})();
function injectFundingPromo(){const feed=screen.querySelector('.feed-section');if(!feed||screen.querySelector('.funding-promo'))return;feed.insertAdjacentHTML('afterend','<button class="funding-promo" data-go="role-select" aria-label="피시 펀딩 시작하기"><span class="promo-label">AD · 피시 펀딩</span><strong>오늘의 응원이<br>내일의 풍요로운 바다를 만듭니다</strong><small>어선을 응원하고 산지 직송 수산물을 만나보세요</small><i>⚓</i><b>응원 시작하기 ›</b></button>')}
new MutationObserver(injectFundingPromo).observe(screen,{childList:true,subtree:true});
injectFundingPromo();
function makeFundingPromoStatic(){screen.querySelectorAll('button.funding-promo').forEach(button=>{const promo=document.createElement('aside');promo.className='funding-promo';promo.setAttribute('aria-label','피시 펀딩 안내');promo.innerHTML=button.innerHTML;button.replaceWith(promo)})}
new MutationObserver(makeFundingPromoStatic).observe(screen,{childList:true,subtree:true});
makeFundingPromoStatic();
(()=>{const data=db(),harbor=data.boats.find(boat=>boat.id==='safe-harbor');if(harbor){harbor.logs??=[];if(!harbor.logs.length)harbor.logs.push({date:'2026. 07. 29.',title:'응원금으로 안전한 선박 수리를 진행합니다',text:'응원자분들이 보내주신 마음 덕분에 갑판과 장비를 정비하고 있습니다.',photos:[]});harbor.logs[0].photos=['assets/feed-repair-boat.png']}save(data);ensureCommunityExamples()})();
function canBuyFromBoat(data,boatId){const user=activeSupporter(data);return !!user&&(data.supporterSupports?.[user.id]?.[boatId]||0)>0}
function viewProductDetail(boatId,productId){const data=db(),b=boat(boatId),p=b.products.find(x=>x.id===productId),allowed=canBuyFromBoat(data,boatId);screen.innerHTML=back('상품 상세','boats')+`<section class="product-detail"><div class="detail-product-image">${p.photo?`<img src="${p.photo}" alt="${p.name}">`:'🦪'}</div><small>${b.name} · ${b.fisher} 선장</small><h2>${p.name}</h2><strong>${money(p.price)}</strong><p>${p.description||'신선한 산지 직송 수산물입니다.'}</p><div>재고 수량 <b>${p.quantity}개</b></div>${allowed?`<button class="primary-button full" data-order-start-v2="${boatId}|${productId}">구매하기</button>`:`<p class="policy-note">이 어선을 응원한 응원자만 수산물을 구매할 수 있어요.</p><button class="outline-button full" disabled>응원 후 구매 가능</button>`}</section>`}
function viewOrderForm(boatId,productId){const b=boat(boatId),p=b.products.find(x=>x.id===productId);screen.innerHTML=back('주문 정보 입력','boats')+`<form class="form-card" id="order-form-v2"><input type="hidden" name="boatId" value="${boatId}"><input type="hidden" name="productId" value="${productId}"><section class="order-summary"><strong>${p.name}</strong><span>${money(p.price)} · 재고 ${p.quantity}개</span></section><label>구매 수량<input name="quantity" type="number" min="1" max="${p.quantity}" value="1" required></label><label>받는 사람 이름<input name="recipient" required></label><label>연락처<input name="phone" required placeholder="010-0000-0000"></label><label>배송 주소<input name="address" required placeholder="상세 주소까지 입력"></label><label>배송 요청사항<textarea name="request" placeholder="예: 부재 시 문 앞에 놓아 주세요."></textarea></label><button class="primary-button full" type="submit">결제 방식 선택</button></form>`}
function viewPayment(draft){const b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId),total=p.price*draft.quantity,user=activeSupporter(),reward=pointReward(total),usablePoints=Math.min(user.wallet,pointCost(total)),pointValue=usablePoints/POINTS_PER_THOUSAND*1000,remaining=Math.max(0,total-pointValue);sessionStorage.setItem('fishFunding.orderDraft',JSON.stringify(draft));screen.innerHTML=back('결제 방식','support-home')+`<section class="order-summary"><strong>${p.name} × ${draft.quantity}</strong><span>결제 금액 <b>${money(total)}</b></span></section><form class="form-card" id="payment-form-v3"><label><input type="radio" name="payment" value="reservation"> 예약 구매 <small>다음 조업 후 수산물을 확보해 순차 배송합니다.</small></label><label><input type="radio" name="payment" value="card" checked> 카드 결제 <select name="card"><option>테스트 신한카드</option><option>테스트 국민카드</option><option>테스트 현대카드</option></select></label><label><input type="radio" name="payment" value="transfer"> 계좌이체 <small>피시 펀딩 · 1002-000-123456 (테스트 계좌)</small></label><label><input type="radio" name="payment" value="points"> 포인트 먼저 사용 <small>보유 ${user.wallet.toLocaleString()}P 중 ${usablePoints.toLocaleString()}P 사용 · ${money(pointValue)} 할인${remaining?` · 남은 ${money(remaining)}`:' · 추가 결제 없음'}</small><select name="remainder"><option value="card">남은 금액 카드 결제</option><option value="transfer">남은 금액 계좌이체</option></select></label><p class="policy-note">포인트는 1,000원당 100P로 환산되며, 구매 시 1,000원당 20P가 적립됩니다.</p><button class="primary-button full" type="submit">테스트 결제 완료</button></form>`}
function viewSupportPayment(draft){const b=boat(draft.boatId);sessionStorage.setItem('fishFunding.supportDraft',JSON.stringify(draft));screen.innerHTML=back('응원 결제','boats')+`<section class="order-summary"><strong>${b.name} 응원</strong><span>결제 금액 <b>${money(draft.amount)}</b></span></section><form class="form-card" id="support-payment-form-v2"><label><input type="radio" name="payment" value="card" checked> 카드 결제 <select name="card"><option>테스트 신한카드</option><option>테스트 국민카드</option><option>테스트 현대카드</option></select></label><label>카드 번호<input name="cardNumber" inputmode="numeric" placeholder="0000-0000-0000-0000"></label><label><input type="radio" name="payment" value="transfer"> 계좌이체 <small>피시 펀딩 · 1002-000-123456 (테스트 계좌)</small></label><p class="policy-note">계좌이체는 주문 후 ‘입금 확인 대기’ 상태로 저장됩니다.</p><button class="primary-button full" type="submit">테스트 결제 완료</button></form>`}
screen.addEventListener('click',e=>{const button=e.target.closest('[data-order-start-v2]');if(!button)return;const [boatId,productId]=button.dataset.orderStartV2.split('|');if(!canBuyFromBoat(db(),boatId)){toast('응원한 어선의 수산물만 구매할 수 있어요.');return}viewOrderForm(boatId,productId)});
screen.addEventListener('submit',e=>{const form=e.target;if(form.id!=='order-form-v2'&&form.id!=='payment-form-v3'&&form.id!=='support-payment-form-v2')return;e.preventDefault();e.stopImmediatePropagation();const data=db(),values=new FormData(form);if(form.id==='order-form-v2'){const boatId=values.get('boatId');if(!canBuyFromBoat(data,boatId)){toast('응원한 어선의 수산물만 구매할 수 있어요.');return}viewPayment({boatId,productId:values.get('productId'),quantity:Number(values.get('quantity')),recipient:values.get('recipient'),phone:values.get('phone'),address:values.get('address'),request:values.get('request')});return}if(form.id==='support-payment-form-v2'){const draft=JSON.parse(sessionStorage.getItem('fishFunding.supportDraft')),payment=values.get('payment');if(payment==='card'&&!String(values.get('cardNumber')).trim()){toast('테스트 카드 번호를 입력해 주세요.');return}data.supportPayments??=[];data.supports[draft.boatId]=(data.supports[draft.boatId]||0)+draft.amount;data.supporterSupports[draft.supporterId]??={};data.supporterSupports[draft.supporterId][draft.boatId]=(data.supporterSupports[draft.supporterId][draft.boatId]||0)+draft.amount;data.supportPayments.push({id:'support-'+Date.now(),boatId:draft.boatId,supporterId:draft.supporterId,amount:draft.amount,payment,paymentLabel:payment==='card'?'카드 결제':'계좌이체',status:payment==='card'?'결제 완료':'입금 확인 대기',date:today()});save(data);sessionStorage.removeItem('fishFunding.supportDraft');toast(payment==='card'?'응원 결제가 완료되었습니다. 감사합니다!':'응원 주문이 접수되었습니다. 입금 확인을 기다려 주세요.');viewMyBoats();return}const draft=JSON.parse(sessionStorage.getItem('fishFunding.orderDraft')),user=activeSupporter(data),b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId);if(!canBuyFromBoat(data,b.id)){toast('응원한 어선의 수산물만 구매할 수 있어요.');return}const policy=purchasePolicy(data,draft,user,b,p);if(policy.blocked){toast(policy.blocked);return}if(draft.quantity>p.quantity){toast('재고 수량이 부족합니다.');return}const total=p.price*draft.quantity,payment=values.get('payment'),reward=pointReward(total),usablePoints=payment==='points'?Math.min(user.wallet,pointCost(total)):0,pointValue=usablePoints/POINTS_PER_THOUSAND*1000,remaining=Math.max(0,total-pointValue),remainder=remaining?values.get('remainder'):null,pointDelta=reward-usablePoints;user.wallet+=pointDelta;p.quantity-=draft.quantity;const labels={reservation:'예약 구매',card:'카드 결제',transfer:'계좌이체',points:remaining?`포인트 ${usablePoints.toLocaleString()}P + ${remainder==='transfer'?'계좌이체':'카드 결제'}`:`포인트 결제 (${usablePoints.toLocaleString()}P)`},limited=p.quantity<=3;const order={id:'order-'+Date.now(),supporterId:user.id,fisherId:b.ownerId||null,boatId:b.id,productId:p.id,productName:p.name,quantity:draft.quantity,total,payment,paymentLabel:labels[payment],status:limited?'대기열 대기':payment==='transfer'||(payment==='points'&&remainder==='transfer')?'결제 대기':payment==='reservation'?'상품 준비 중':'결제 완료',recipient:draft.recipient,phone:draft.phone,address:draft.address,request:draft.request,date:today(),createdAt:new Date().toISOString(),priority:policy.priority,review:policy.review,pointDelta,pointCost:usablePoints,pointReward:reward,remainingPayment:remaining};data.orders.push(order);if(pointDelta)addPointHistory(data,user.id,pointDelta,payment==='points'?`포인트 사용 · ${p.name}`:`구매 적립 · ${p.name}`);save(data);sessionStorage.removeItem('fishFunding.orderDraft');toast(`주문이 완료되었습니다. 포인트 ${pointDelta>0?'+':''}${pointDelta.toLocaleString()}P`);viewMyOrders()},true);
var communityExamplesBase=ensureCommunityExamples;ensureCommunityExamples=function(){const data=communityExamplesBase();const weatherPost=data.posts.find(post=>post.id==='example-talk-1'),reviewPost=data.posts.find(post=>post.id==='welcome-review');if(weatherPost)weatherPost.photo='assets/community-tongyeong-sea.png';if(reviewPost)reviewPost.photo='assets/review-red-seabream.png';save(data);return data};ensureCommunityExamples();
function viewPayment(draft){const b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId),total=p.price*draft.quantity,user=activeSupporter(),reward=pointReward(total);sessionStorage.setItem('fishFunding.orderDraft',JSON.stringify(draft));screen.innerHTML=back('결제 방식','support-home')+`<section class="order-summary"><strong>${p.name} × ${draft.quantity}</strong><span>결제 금액 <b>${money(total)}</b></span></section><form class="form-card" id="payment-form-v4"><label><input type="radio" name="payment" value="reservation"> 예약 구매 <small>다음 조업 후 수산물을 확보해 순차 배송합니다.</small></label><label><input type="radio" name="payment" value="card" checked> 카드 결제 <select name="card"><option>테스트 신한카드</option><option>테스트 국민카드</option><option>테스트 현대카드</option></select></label><label><input type="radio" name="payment" value="transfer"> 계좌이체 <small>피시 펀딩 · 1002-000-123456 (테스트 계좌)</small></label><label><input type="radio" name="payment" value="points"> 포인트 먼저 사용 <small>보유 ${user.wallet.toLocaleString()}P · 구매 적립 +${reward.toLocaleString()}P</small><select name="pointUse"><option value="100">100P 사용</option><option value="1000">1,000P 사용</option><option value="5000">5,000P 사용</option><option value="all">전액 사용</option></select><small>선택한 포인트만 먼저 사용하고, 남은 금액은 아래 방식으로 결제합니다.</small><select name="remainder"><option value="card">남은 금액 카드 결제</option><option value="transfer">남은 금액 계좌이체</option></select></label><p class="policy-note">포인트는 100P 단위로 사용되며, 1,000원당 100P로 환산됩니다.</p><button class="primary-button full" type="submit">테스트 결제 완료</button></form>`}
screen.addEventListener('submit',e=>{const form=e.target;if(form.id!=='payment-form-v4')return;e.preventDefault();e.stopImmediatePropagation();const data=db(),draft=JSON.parse(sessionStorage.getItem('fishFunding.orderDraft')),user=activeSupporter(data),b=boat(draft.boatId),p=b.products.find(x=>x.id===draft.productId);if(!canBuyFromBoat(data,b.id)){toast('응원한 어선의 수산물만 구매할 수 있어요.');return}const policy=purchasePolicy(data,draft,user,b,p);if(policy.blocked){toast(policy.blocked);return}if(draft.quantity>p.quantity){toast('재고 수량이 부족합니다.');return}const values=new FormData(form),total=p.price*draft.quantity,payment=values.get('payment'),reward=pointReward(total),requested=values.get('pointUse')==='all'?user.wallet:Number(values.get('pointUse')),usablePoints=payment==='points'?Math.min(user.wallet,pointCost(total),requested):0,pointValue=usablePoints/POINTS_PER_THOUSAND*1000,remaining=Math.max(0,total-pointValue),remainder=remaining?values.get('remainder'):null,pointDelta=reward-usablePoints;user.wallet+=pointDelta;p.quantity-=draft.quantity;const labels={reservation:'예약 구매',card:'카드 결제',transfer:'계좌이체',points:remaining?`포인트 ${usablePoints.toLocaleString()}P + ${remainder==='transfer'?'계좌이체':'카드 결제'}`:`포인트 결제 (${usablePoints.toLocaleString()}P)`},limited=p.quantity<=3;data.orders.push({id:'order-'+Date.now(),supporterId:user.id,fisherId:b.ownerId||null,boatId:b.id,productId:p.id,productName:p.name,quantity:draft.quantity,total,payment,paymentLabel:labels[payment],status:limited?'대기열 대기':payment==='transfer'||(payment==='points'&&remainder==='transfer')?'결제 대기':payment==='reservation'?'상품 준비 중':'결제 완료',recipient:draft.recipient,phone:draft.phone,address:draft.address,request:draft.request,date:today(),createdAt:new Date().toISOString(),priority:policy.priority,review:policy.review,pointDelta,pointCost:usablePoints,pointReward:reward,remainingPayment:remaining});if(pointDelta)addPointHistory(data,user.id,pointDelta,payment==='points'?`포인트 사용 · ${p.name}`:`구매 적립 · ${p.name}`);save(data);sessionStorage.removeItem('fishFunding.orderDraft');toast(`주문이 완료되었습니다. 포인트 ${pointDelta>0?'+':''}${pointDelta.toLocaleString()}P`);viewMyOrders()},true);
function addMissingPointOptions(){const select=document.querySelector('#payment-form-v4 select[name="pointUse"]');if(!select)return;[{value:'500',label:'500P 사용'},{value:'2000',label:'2,000P 사용'}].forEach(item=>{if([...select.options].some(option=>option.value===item.value))return;const option=document.createElement('option');option.value=item.value;option.textContent=item.label;const all=select.querySelector('option[value="all"]');select.insertBefore(option,all)})}
new MutationObserver(addMissingPointOptions).observe(screen,{childList:true,subtree:true});
addMissingPointOptions();
(()=>{const data=db(),baseFunds={'blue-sea':1280000,sunrise:960000,'sea-star':740000,'safe-harbor':680000};Object.entries(baseFunds).forEach(([boatId,amount])=>{if(!data.supports[boatId])data.supports[boatId]=amount});save(data);if(screen.querySelector('.investment-carousel'))viewHome()})();
